use std::{path::PathBuf, process::{Command,Stdio}};
#[tauri::command] pub fn screen_capture()->Result<String,String>{if !cfg!(target_os="macos"){return Err("Screen capture requires the macOS desktop build and Screen Recording permission.".into())}let dir=dirs::cache_dir().unwrap_or_else(||PathBuf::from("/tmp")).join("jarvis");std::fs::create_dir_all(&dir).map_err(|e|e.to_string())?;let path=dir.join(format!("screen-{}.png",chrono::Utc::now().timestamp_millis()));let status=Command::new("screencapture").args(["-x","-m",path.to_str().unwrap_or_default()]).status().map_err(|e|e.to_string())?;if status.success(){Ok(path.to_string_lossy().into())}else{Err("macOS denied screen capture. Enable Screen Recording for JARVIS.".into())}}
#[tauri::command] pub fn speak(text:String,voice:String,speed:f32)->Result<(),String>{if !cfg!(target_os="macos"){return Err("Local TTS requires the macOS desktop build.".into())}if text.trim().is_empty(){return Ok(())}let rate=(speed.clamp(0.25,4.0)*175.0) as i32;Command::new("say").args(["-v",&voice,"-r",&rate.to_string(),&text]).stdout(Stdio::null()).stderr(Stdio::null()).spawn().map(|_|()).map_err(|e|e.to_string())}
#[tauri::command] pub fn stop_speaking()->Result<(),String>{if !cfg!(target_os="macos"){return Err("Local TTS requires the macOS desktop build.".into())}let _=Command::new("pkill").args(["-x","say"]).status();Ok(())}
